const input = $json || {};

const sampleActions = [
  {
    actionId: 'social-1-show-1',
    recommendationId: 'social-1',
    recommendationTitle: 'International Social Mixer',
    type: 'show_recommendation',
    title: 'Show recommendation: International Social Mixer',
    description: 'Present the recommendation to the user.',
    payload: {},
    channel: 'chatgpt',
    scheduledFor: null,
    priority: 'high',
    riskLevel: 'low',
    approvalRequired: false,
    autoExecutable: true,
    status: 'planned',
    createdAt: new Date().toISOString()
  },
  {
    actionId: 'social-1-calendar-2',
    recommendationId: 'social-1',
    recommendationTitle: 'International Social Mixer',
    type: 'calendar_create',
    title: 'Add International Social Mixer to calendar',
    description: 'Prepare a Google Calendar event for user approval.',
    payload: {
      title: 'International Social Mixer',
      start: '2026-08-01T20:00:00+04:00',
      end: '2026-08-01T23:00:00+04:00',
      location: 'Dubai Marina'
    },
    channel: null,
    scheduledFor: null,
    priority: 'high',
    riskLevel: 'medium',
    approvalRequired: true,
    autoExecutable: false,
    status: 'planned',
    createdAt: new Date().toISOString()
  },
  {
    actionId: 'social-1-reminder-3',
    recommendationId: 'social-1',
    recommendationTitle: 'International Social Mixer',
    type: 'personal_reminder',
    title: 'Reminder for International Social Mixer',
    description: 'Prepare a personal reminder.',
    payload: {
      eventTitle: 'International Social Mixer',
      reminderMinutesBefore: 60
    },
    channel: 'telegram',
    scheduledFor: '2026-08-01T20:00:00+04:00',
    priority: 'normal',
    riskLevel: 'low',
    approvalRequired: false,
    autoExecutable: true,
    status: 'planned',
    createdAt: new Date().toISOString()
  },
  {
    actionId: 'travel-1-purchase-4',
    recommendationId: 'travel-1',
    recommendationTitle: 'Weekend Trip',
    type: 'purchase_execute',
    title: 'Purchase trip booking',
    description: 'Attempt to purchase a booking.',
    payload: {
      amount: 1200,
      currency: 'AED'
    },
    channel: null,
    scheduledFor: null,
    priority: 'high',
    riskLevel: 'high',
    approvalRequired: true,
    autoExecutable: false,
    status: 'planned',
    createdAt: new Date().toISOString()
  }
];

let actions = [];

if (Array.isArray(input.actions)) {
  actions = input.actions;
} else if (Array.isArray(input.result?.actions)) {
  actions = input.result.actions;
} else if (Array.isArray(input.actionPlannerOutput?.result?.actions)) {
  actions = input.actionPlannerOutput.result.actions;
} else {
  actions = sampleActions;
}

return [{
  json: {
    request: input.request || {
      text: 'Bu akşam ne yapayım?',
      channel: 'manual_test',
      userId: 'savas',
      conversationId: 'manual-test'
    },
    context: input.context || {
      timezone: 'Asia/Dubai',
      userContext: {
        identity: { name: 'Savaş', language: 'Turkish' }
      }
    },
    actions,
    userResponse: input.userResponse || null,
    metadata: input.metadata || {
      correlationId: `approval-${Date.now()}`,
      testMode: true
    }
  }
}];

const input = $json || {};
const actions = Array.isArray(input.actions) ? input.actions : [];
const userResponse = input.userResponse || null;
const metadata = input.metadata || {};

const approvalRequiredTypes = new Set([
  'calendar_create',
  'calendar_update',
  'calendar_delete',
  'send_external_message',
  'send_email',
  'reservation_prepare',
  'reservation_execute',
  'purchase_prepare',
  'purchase_execute',
  'share_personal_data'
]);

const blockedTypes = new Set([
  'purchase_execute',
  'reservation_execute'
]);

const autoApprovedTypes = new Set([
  'show_recommendation',
  'personal_reminder',
  'preparation_checklist',
  'fitness_preparation',
  'travel_plan',
  'feedback_request',
  'memory_update',
  'format_notification'
]);

const createToken = actionId =>
  `apr_${Buffer.from(`${actionId}:${Date.now()}`)
    .toString('base64')
    .replace(/=/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .slice(0, 32)}`;

const normalizeDecision = value => {
  const normalized = String(value || '')
    .trim()
    .toLowerCase();

  if (['approve', 'approved', 'yes', 'evet', 'accept', 'accepted'].includes(normalized)) {
    return 'approved';
  }

  if (['reject', 'rejected', 'no', 'hayir', 'hayır', 'decline', 'declined'].includes(normalized)) {
    return 'rejected';
  }

  if (['alternative', 'alternatives', 'show alternatives', 'alternatif'].includes(normalized)) {
    return 'alternative_requested';
  }

  return null;
};

const responseDecision = normalizeDecision(
  userResponse?.decision ||
  userResponse?.text ||
  userResponse?.value
);

const responseActionId =
  userResponse?.actionId ||
  userResponse?.approvalId ||
  null;

const evaluatedActions = [];
const pendingApprovals = [];
const autoApprovedActions = [];
const blockedActions = [];
const rejectedActions = [];
const logs = [];

for (const action of actions) {
  if (!action?.actionId || !action?.type) {
    logs.push({
      level: 'warning',
      message: 'Skipped malformed action.',
      details: { action }
    });
    continue;
  }

  const type = String(action.type);
  const riskLevel =
    action.riskLevel ||
    (
      blockedTypes.has(type)
        ? 'high'
        : approvalRequiredTypes.has(type)
          ? 'medium'
          : 'low'
    );

  const approvalRequired =
    Boolean(action.approvalRequired) ||
    approvalRequiredTypes.has(type);

  let status = 'planned';
  let reason = '';
  let approvalToken = null;

  const userRespondedToThisAction =
    responseDecision &&
    responseActionId &&
    responseActionId === action.actionId;

  if (blockedTypes.has(type)) {
    status = 'blocked';
    reason =
      'Execution of purchases or reservations is not supported. The system may prepare options but cannot complete the transaction.';
    blockedActions.push({
      ...action,
      status,
      reason,
      riskLevel
    });
  } else if (userRespondedToThisAction) {
    if (responseDecision === 'approved') {
      status = 'approved';
      reason = 'Explicitly approved by the user.';
      autoApprovedActions.push({
        ...action,
        status,
        reason,
        riskLevel,
        approvedAt: new Date().toISOString()
      });
    } else if (responseDecision === 'rejected') {
      status = 'rejected';
      reason = 'Explicitly rejected by the user.';
      rejectedActions.push({
        ...action,
        status,
        reason,
        riskLevel,
        rejectedAt: new Date().toISOString()
      });
    } else if (responseDecision === 'alternative_requested') {
      status = 'alternative_requested';
      reason = 'The user requested an alternative.';
      rejectedActions.push({
        ...action,
        status,
        reason,
        riskLevel
      });
    }
  } else if (approvalRequired) {
    status = 'pending_approval';
    reason = 'Explicit user approval is required before this action can proceed.';
    approvalToken = createToken(action.actionId);

    pendingApprovals.push({
      approvalId: approvalToken,
      actionId: action.actionId,
      recommendationId: action.recommendationId || null,
      type,
      status,
      riskLevel,
      summary: action.title,
      description: action.description || '',
      payload: action.payload || {},
      channel: action.channel || 'telegram',
      createdAt: new Date().toISOString(),
      expiresAt: new Date(
        Date.now() + 24 * 60 * 60 * 1000
      ).toISOString(),
      allowedResponses: [
        'approve',
        'reject',
        'alternative'
      ]
    });
  } else if (
    action.autoExecutable === true ||
    autoApprovedTypes.has(type)
  ) {
    status = 'approved';
    reason = 'Low-risk internal action approved automatically.';
    autoApprovedActions.push({
      ...action,
      status,
      reason,
      riskLevel,
      approvedAt: new Date().toISOString()
    });
  } else {
    status = 'pending_review';
    reason = 'Action does not match a known rule and requires manual review.';
    approvalToken = createToken(action.actionId);

    pendingApprovals.push({
      approvalId: approvalToken,
      actionId: action.actionId,
      recommendationId: action.recommendationId || null,
      type,
      status: 'pending_approval',
      riskLevel: 'medium',
      summary: action.title,
      description: action.description || '',
      payload: action.payload || {},
      channel: action.channel || 'telegram',
      createdAt: new Date().toISOString(),
      expiresAt: new Date(
        Date.now() + 24 * 60 * 60 * 1000
      ).toISOString(),
      allowedResponses: [
        'approve',
        'reject',
        'alternative'
      ]
    });
  }

  evaluatedActions.push({
    ...action,
    riskLevel,
    approvalRequired,
    approvalStatus: status,
    approvalReason: reason,
    approvalToken
  });
}

const notificationItems = pendingApprovals.map(item => ({
  notificationType: 'approval_request',
  preferredChannel: 'telegram',
  fallbackChannel: 'whatsapp',
  title: item.summary,
  message:
    `${item.summary}\n\nRisk: ${item.riskLevel}\n\nApprove this action?`,
  buttons: [
    {
      label: 'Approve',
      value: `approve:${item.actionId}`
    },
    {
      label: 'Reject',
      value: `reject:${item.actionId}`
    },
    {
      label: 'Alternative',
      value: `alternative:${item.actionId}`
    }
  ],
  approvalId: item.approvalId,
  actionId: item.actionId
}));

const summary = {
  inputActionCount: actions.length,
  evaluatedActionCount: evaluatedActions.length,
  pendingApprovalCount: pendingApprovals.length,
  autoApprovedCount: autoApprovedActions.length,
  blockedCount: blockedActions.length,
  rejectedCount: rejectedActions.length
};

let nextAction;

if (pendingApprovals.length > 0) {
  nextAction = {
    type: 'send_approval_notifications',
    targetWorkflow: 'Concierge OS - Notification Engine'
  };
} else if (autoApprovedActions.length > 0) {
  nextAction = {
    type: 'execute_approved_actions',
    targetWorkflow: 'Concierge OS - Action Executor'
  };
} else {
  nextAction = {
    type: 'stop',
    targetWorkflow: null
  };
}

return [{
  json: {
    success: true,
    result: {
      summary,
      evaluatedActions,
      pendingApprovals,
      autoApprovedActions,
      blockedActions,
      rejectedActions,
      notificationItems
    },
    memoryUpdates: pendingApprovals.map(item => ({
      type: 'pending_approval',
      operation: 'append',
      payload: item
    })),
    approvalRequests: pendingApprovals,
    logs: [
      {
        timestamp: new Date().toISOString(),
        workflow: 'Concierge OS - Approval Engine',
        level:
          blockedActions.length || rejectedActions.length
            ? 'warning'
            : 'info',
        correlationId:
          metadata.correlationId || '',
        message:
          `Evaluated ${evaluatedActions.length} actions.`,
        details: summary
      },
      ...logs.map(log => ({
        timestamp: new Date().toISOString(),
        workflow: 'Concierge OS - Approval Engine',
        correlationId:
          metadata.correlationId || '',
        ...log
      }))
    ],
    nextAction,
    error: null
  }
}];
